def ShortExact (j : BoundedHom 𝕜 I A) (θ : BoundedHom 𝕜 A B) : Prop :=
  Function.Injective j ∧ Function.Surjective θ ∧
    ∀ a, θ a = 0 ↔ a ∈ Set.range j

